  if (!text.startsWith('"')) return undefined;
  const bytes: number[] = [];
  const named: Record<string, number> = { a: 7, b: 8, t: 9, n: 10, v: 11, f: 12, r: 13, '"': 34, "\\": 92 };
  for (let i = 1; i < text.length; i++) {
    const ch = text[i];
    if (ch === '"') {
